sp_widget.client_script:
api.controller = function($scope, $window, $timeout, spUtil, $location) {
  var c = this;

  c.gridView       = true;
  c.activeCategory = 'all';
  c.searchText     = '';
  c.sortKey        = 'name_asc';
  c.currentPage    = 1;
  c.pageSize       = 12;

  var _filtered = [];

  // ── Core filter + sort + paginate ──────────────────
  c.applyFilters = function() {
    var programs = angular.copy(c.data.programs) || [];

    // Category filter
    if (c.activeCategory !== 'all') {
      programs = programs.filter(function(p) {
        return (p.program_category || '').trim() === c.activeCategory.trim();
      });
    }

    // Search filter
    if (c.searchText && c.searchText.trim()) {
      var txt = c.searchText.toLowerCase().trim();
      programs = programs.filter(function(p) {
        return (p.program_name        || '').toLowerCase().indexOf(txt) !== -1 ||
               (p.program_description || '').toLowerCase().indexOf(txt) !== -1 ||
               (p.program_category    || '').toLowerCase().indexOf(txt) !== -1 ||
               (p.program_budget      || '').toLowerCase().indexOf(txt) !== -1;
      });
    }

    // Sort
    programs.sort(function(a, b) {
      if (c.sortKey === 'name_asc')  return (a.program_name || '').localeCompare(b.program_name || '');
      if (c.sortKey === 'name_desc') return (b.program_name || '').localeCompare(a.program_name || '');
      if (c.sortKey === 'budget')    return (b.program_budget || '').localeCompare(a.program_budget || '');
      return 0; // newest — server already ordered
    });

    _filtered = programs;
  };

  // ── Exposed helpers ────────────────────────────────
  c.totalFiltered = function() { return _filtered.length; };

  c.totalPages = function() {
    return Math.ceil(_filtered.length / parseInt(c.pageSize)) || 1;
  };

  c.paged = function() {
    var size  = parseInt(c.pageSize);
    var start = (c.currentPage - 1) * size;
    return _filtered.slice(start, start + size);
  };

  c.pageStart = function() {
    return _filtered.length ? (c.currentPage - 1) * parseInt(c.pageSize) + 1 : 0;
  };

  c.pageEnd = function() {
    return Math.min(c.currentPage * parseInt(c.pageSize), _filtered.length);
  };

  c.pageNumbers = function() {
    var total = c.totalPages(), cur = c.currentPage, pages = [];
    var start = Math.max(1, cur - 2), end = Math.min(total, cur + 2);
    if (start > 1)     { pages.push(1); if (start > 2) pages.push('...'); }
    for (var i = start; i <= end; i++) pages.push(i);
    if (end < total)   { if (end < total - 1) pages.push('...'); pages.push(total); }
    return pages;
  };

  c.goTo = function(p) {
    if (p === '...' || p < 1 || p > c.totalPages()) return;
    c.currentPage = p;
    $timeout(function() {
      var top = document.querySelector('.gp-main');
      if (top) top.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }, 50);
  };

  // ── Filters ────────────────────────────────────────
  c.filterBy = function(cat) {
    c.activeCategory = cat;
    c.currentPage    = 1;
    c.applyFilters();
  };

  c.onSearch = function() {
    c.currentPage = 1;
    c.applyFilters();
  };

  c.clearSearch = function() {
    c.searchText  = '';
    c.currentPage = 1;
    c.applyFilters();
  };

  c.clearAll = function() {
    c.searchText     = '';
    c.activeCategory = 'all';
    c.currentPage    = 1;
    c.applyFilters();
  };

  c.countByCategory = function(cat) {
    return (c.data.programs || []).filter(function(p) {
      return (p.program_category || '').trim() === cat.trim();
    }).length;
  };

 c.viewDetails = function(program) {
  if (!program || !program.sys_id) return;

  $location.search({
    id: 'grant_program_detail',
    sys_id: program.sys_id
  });
};

  // ── Init ───────────────────────────────────────────
  c.applyFilters();
};

sp_widget.css:
/* ── Reset ── */
.gp-programs-wrapper *,
.gp-programs-wrapper *::before,
.gp-programs-wrapper *::after { box-sizing: border-box; margin: 0; padding: 0; }

/* ── Wrapper ── */
.gp-programs-wrapper {
  font-family: 'Inter', 'Segoe UI', sans-serif;
  width: calc(100% + 30px);
  margin-left: -15px;
  margin-right: -15px;
  background: #f4f5f9;
}

/* ════════════════════════════════════════════════
   HERO
════════════════════════════════════════════════ */
.gp-hero {
  background: linear-gradient(114deg, #3d2e9c 0%, #5443ad 55%, #6b7fd4 100%);
  padding: 66px 0 52px;
  position: relative;
  overflow: hidden;

  &::before {
    content: '';
    position: absolute;
    top: -80px; right: -60px;
    width: 340px; height: 340px;
    border-radius: 50%;
    background: rgba(255,255,255,0.04);
    pointer-events: none;
  }
}

.gp-hero__inner {
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 48px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 40px;
  flex-wrap: wrap;
}

.gp-hero__left { flex: 1; min-width: 280px; }

/* Badge */
.gp-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(255,255,255,0.12);
  border: 1px solid rgba(255,255,255,0.25);
  color: rgba(255,255,255,0.9);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 5px 14px;
  border-radius: 100px;
  margin-bottom: 16px;
  backdrop-filter: blur(6px);
}

.gp-badge-dot {
  width: 6px; height: 6px;
  border-radius: 50%;
  background: #7dd3fc;
  box-shadow: 0 0 6px rgba(125,211,252,0.9);
  flex-shrink: 0;
  animation: gpPulse 2.2s ease-in-out infinite;
}

@keyframes gpPulse {
  0%,100% { transform: scale(1); opacity: 1; }
  50%      { transform: scale(1.7); opacity: 0.45; }
}

.gp-hero__title {
  font-size: clamp(22px, 2.6vw, 34px);
  font-weight: 800;
  color: #fff;
  line-height: 1.2;
  letter-spacing: -0.02em;
  margin-bottom: 12px;
}

.gp-hero__sub {
  font-size: 14px;
  color: rgba(255,255,255,0.70);
  line-height: 1.7;
  margin-bottom: 24px;
  max-width: 520px;
}

/* Search */
.gp-search-wrap {
  position: relative;
  max-width: 480px;
}

.gp-search-icon {
  position: absolute;
  left: 14px; top: 50%;
  transform: translateY(-50%);
  width: 16px; height: 16px;
  color: rgba(255,255,255,0.55);
  pointer-events: none;
}

.gp-search-input {
  width: 100%;
  padding: 12px 42px 12px 40px;
  background: rgba(255,255,255,0.14);
  border: 1px solid rgba(255,255,255,0.25);
  border-radius: 12px;
  font-size: 13.5px;
  color: #fff;
  font-family: inherit;
  backdrop-filter: blur(8px);
  outline: none;
  transition: background 0.2s, border-color 0.2s;

  &::placeholder { color: rgba(255,255,255,0.5); }

  &:focus {
    background: rgba(255,255,255,0.20);
    border-color: rgba(255,255,255,0.45);
  }
}

.gp-search-clear {
  position: absolute;
  right: 12px; top: 50%;
  transform: translateY(-50%);
  background: rgba(255,255,255,0.2);
  border: none;
  border-radius: 4px;
  width: 22px; height: 22px;
  display: flex; align-items: center; justify-content: center;
  color: #fff;
  cursor: pointer;
  transition: background 0.15s;

  &:hover { background: rgba(255,255,255,0.35); }
}

/* Stats pills */
.gp-hero__stats {
  display: flex;
  flex-direction: column;
  gap: 10px;
  flex-shrink: 0;
}

.gp-stat-pill {
  display: flex;
  align-items: center;
  gap: 12px;
  background: rgba(255,255,255,0.12);
  border: 1px solid rgba(255,255,255,0.18);
  border-radius: 12px;
  padding: 12px 20px;
  backdrop-filter: blur(6px);
  min-width: 160px;
  transition: background 0.18s;

  &:hover { background: rgba(255,255,255,0.20); }
}

.gp-stat-pill__num {
  font-size: 26px;
  font-weight: 900;
  color: #fff;
  line-height: 1;
}

.gp-stat-pill__lbl {
  font-size: 11px;
  font-weight: 600;
  color: rgba(255,255,255,0.58);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

/* ════════════════════════════════════════════════
   BODY
════════════════════════════════════════════════ */
.gp-body {
  background: #f4f5f9;
  padding: 32px 0 72px;
}

.gp-body__inner {
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 48px;
}

/* ── Toolbar ── */
.gp-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 20px;
  flex-wrap: wrap;
}

.gp-toolbar__left {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}

.gp-result-count {
  font-size: 13px;
  color: #6b7280;
  font-weight: 500;

  strong { color: #1e293b; }
}

.gp-sort-wrap {
  display: flex;
  align-items: center;
  gap: 6px;
  background: #fff;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  padding: 0 12px;
  height: 34px;
}

.gp-sort-icon { color: #9ca3af; flex-shrink: 0; }

.gp-sort-select {
  border: none;
  background: transparent;
  font-size: 12.5px;
  font-family: inherit;
  color: #374151;
  font-weight: 500;
  outline: none;
  cursor: pointer;
}

.gp-view-toggle {
  display: flex;
  align-items: center;
  gap: 3px;
  background: #fff;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  padding: 3px;
}

.gp-toggle-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 30px; height: 30px;
  border-radius: 6px;
  border: none;
  background: transparent;
  color: #9ca3af;
  cursor: pointer;
  transition: all 0.15s;

  &--active { background: #5443ad; color: #fff; }
  &:hover:not(.gp-toggle-btn--active) { background: #f3f4f6; color: #374151; }
}

/* ── Layout: sidebar + main ── */
.gp-layout {
  display: flex;
  gap: 24px;
  align-items: flex-start;
}

/* ════════════════════════════════════════════════
   CATEGORY SIDEBAR
════════════════════════════════════════════════ */
.gp-sidebar {
  width: 220px;
  flex-shrink: 0;
  background: #fff;
  border: 1px solid #e9eaf0;
  border-radius: 14px;
  overflow: hidden;
  position: sticky;
  top: 16px;
}

.gp-sidebar__hdr {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 14px 16px 12px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: #94a3b8;
  border-bottom: 1px solid #f1f5f9;
}

.gp-cat-list {
  list-style: none;
  padding: 8px 0;
  max-height: 520px;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: #e2e8f0 transparent;

  &::-webkit-scrollbar { width: 4px; }
  &::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 99px; }
}

.gp-cat-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 9px 16px;
  cursor: pointer;
  border-radius: 0;
  transition: background 0.15s, color 0.15s;
  border-left: 3px solid transparent;

  &:hover { background: #f8fafc; }

  &--active {
    background: rgba(84,67,173,0.07);
    border-left-color: #5443ad;

    .gp-cat-item__name { color: #5443ad; font-weight: 700; }
    .gp-cat-item__count { background: #5443ad; color: #fff; }
  }
}

.gp-cat-item__name {
  font-size: 13px;
  font-weight: 500;
  color: #374151;
  flex: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.gp-cat-item__count {
  font-size: 10px;
  font-weight: 700;
  background: #f1f5f9;
  color: #6b7280;
  padding: 2px 7px;
  border-radius: 99px;
  flex-shrink: 0;
  transition: background 0.15s, color 0.15s;
}

/* ── Main content ── */
.gp-main { flex: 1; min-width: 0; }

/* ── Active filters strip ── */
.gp-active-filters {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 16px;
  padding: 10px 14px;
  background: #fff;
  border: 1px solid #e9eaf0;
  border-radius: 10px;
}

.gp-af-label {
  font-size: 12px;
  font-weight: 600;
  color: #94a3b8;
}

.gp-af-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  background: rgba(84,67,173,0.08);
  color: #5443ad;
  font-size: 12px;
  font-weight: 600;
  padding: 3px 10px;
  border-radius: 100px;

  button {
    background: none;
    border: none;
    color: #5443ad;
    cursor: pointer;
    font-size: 14px;
    line-height: 1;
    padding: 0;
    display: flex; align-items: center;
  }
}

.gp-af-clear {
  margin-left: auto;
  background: none;
  border: none;
  font-size: 12px;
  font-weight: 600;
  color: #ef4444;
  cursor: pointer;
  font-family: inherit;

  &:hover { text-decoration: underline; }
}

/* ════════════════════════════════════════════════
   GRID + CARDS
════════════════════════════════════════════════ */
.gp-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 18px;
  margin-bottom: 28px;

  &--list { grid-template-columns: 1fr; gap: 10px; }
}

.gp-card {
  background: #fff;
  border: 1px solid #e9eaf0;
  border-radius: 14px;
  padding: 20px 20px 16px;
  display: flex;
  flex-direction: column;
  cursor: pointer;
  transition: box-shadow 0.2s, transform 0.2s, border-color 0.2s;

  &:hover {
    box-shadow: 0 8px 28px rgba(84,67,173,0.11);
    transform: translateY(-2px);
    border-color: rgba(84,67,173,0.28);
  }
}

/* List view overrides */
.gp-grid--list .gp-card {
  flex-direction: row;
  align-items: center;
  gap: 20px;
  padding: 16px 20px;

  .gp-card-desc   { display: none; }
  .gp-card-meta   { flex-direction: row; gap: 14px; margin-bottom: 0; flex-wrap: wrap; }
  .gp-card-footer { margin-top: 0; margin-left: auto; border-top: none; padding-top: 0; flex-shrink: 0; }
  .gp-card__top   { margin-bottom: 4px; }
  .gp-card-title  { font-size: 14px; margin-bottom: 4px; }
}

.gp-card__top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 10px;
  flex-wrap: wrap;
}

.gp-card-badge {
  display: inline-flex;
  align-items: center;
  background: rgba(84,67,173,0.08);
  color: #5443ad;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 3px 9px;
  border-radius: 100px;
}

.gp-card-status {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 10px;
  font-weight: 700;
  padding: 3px 9px;
  border-radius: 100px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.gp-status--active  { background: #dcfce7; color: #15803d; }
.gp-status--inactive{ background: #f1f5f9; color: #64748b; }

.gp-status-dot {
  width: 5px; height: 5px;
  border-radius: 50%;
  background: currentColor;
}

.gp-card-title {
  font-size: 14.5px;
  font-weight: 700;
  color: #0f172a;
  line-height: 1.4;
  margin-bottom: 8px;
}

.gp-card-desc {
  font-size: 12.5px;
  color: #6b7280;
  line-height: 1.6;
  margin-bottom: 14px;
  flex: 1;
}

.gp-card-meta {
  display: flex;
  flex-direction: column;
  gap: 5px;
  margin-bottom: 14px;
}

.gp-meta-row {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: #6b7280;
}

.gp-meta-icon {
  width: 13px; height: 13px;
  color: #9ca3af;
  flex-shrink: 0;
}

.gp-card-footer {
  margin-top: auto;
  padding-top: 14px;
  border-top: 1px solid #f1f1f4;
}

.gp-card-link {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 12.5px;
  font-weight: 700;
  color: #5443ad;
  transition: gap 0.18s;
}

.gp-card:hover .gp-card-link { gap: 9px; }

/* ── Empty state ── */
.gp-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 72px 0;
  color: #9ca3af;
  text-align: center;

  strong { font-size: 15px; color: #374151; }
  p      { font-size: 13px; }
}

.gp-btn-reset {
  margin-top: 8px;
  background: #5443ad;
  color: #fff;
  border: none;
  border-radius: 8px;
  padding: 9px 22px;
  font-size: 13px;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  transition: background 0.18s;

  &:hover { background: #4336a0; }
}

/* ════════════════════════════════════════════════
   PAGINATION
════════════════════════════════════════════════ */
.gp-pagination {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  padding: 16px 20px;
  background: #fff;
  border: 1px solid #e9eaf0;
  border-radius: 12px;
}

.gp-pagination__info {
  font-size: 12.5px;
  color: #6b7280;
  font-weight: 500;
  white-space: nowrap;
}

.gp-pagination__controls {
  display: flex;
  align-items: center;
  gap: 4px;
}

.gp-pg-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 34px;
  height: 34px;
  padding: 0 10px;
  border-radius: 8px;
  border: 1px solid #e5e7eb;
  background: #fff;
  font-size: 13px;
  font-weight: 600;
  color: #374151;
  cursor: pointer;
  font-family: inherit;
  transition: background 0.15s, border-color 0.15s, color 0.15s;

  &:hover:not([disabled]):not(.gp-pg-btn--active) {
    background: #f3f4f6;
    border-color: #d1d5db;
  }

  &--active {
    background: #5443ad;
    border-color: #5443ad;
    color: #fff;
  }

  &--ellipsis {
    border-color: transparent;
    background: transparent;
    cursor: default;
    color: #9ca3af;
  }

  &[disabled] {
    opacity: 0.4;
    cursor: not-allowed;
  }
}

.gp-pagination__size {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12.5px;
  color: #6b7280;
  font-weight: 500;

  select {
    border: 1px solid #e5e7eb;
    border-radius: 7px;
    padding: 4px 8px;
    font-size: 12.5px;
    font-family: inherit;
    color: #374151;
    font-weight: 600;
    background: #fff;
    outline: none;
    cursor: pointer;
  }
}

/* ════════════════════════════════════════════════
   RESPONSIVE
════════════════════════════════════════════════ */
@media (max-width: 1100px) {
  .gp-hero__inner,
  .gp-body__inner { padding: 0 32px; }
  .gp-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 900px) {
  .gp-layout { flex-direction: column; }
  .gp-sidebar { width: 100%; position: static;
    .gp-cat-list { display: flex; flex-wrap: wrap; gap: 6px; padding: 12px; max-height: none; overflow: visible; }
    .gp-cat-item { border-left: none; border-radius: 100px; padding: 6px 12px;
      border: 1px solid #e5e7eb; background: #fff;
      &--active { background: #5443ad; border-color: #5443ad;
        .gp-cat-item__name { color: #fff; }
        .gp-cat-item__count { background: rgba(255,255,255,0.3); color: #fff; }
      }
    }
  }
}

@media (max-width: 768px) {
  .gp-hero { padding: 40px 0 38px; }
  .gp-hero__inner { flex-direction: column; gap: 28px; padding: 0 20px; }
  .gp-hero__stats { flex-direction: row; gap: 10px; flex-wrap: wrap; }
  .gp-stat-pill { flex: 1; min-width: 80px; padding: 10px 14px; }
  .gp-body__inner { padding: 0 16px; }
  .gp-grid { grid-template-columns: 1fr; }
  .gp-pagination { flex-direction: column; align-items: flex-start; gap: 12px; }
}

@media (max-width: 480px) {
  .gp-hero__title { font-size: 22px; }
  .gp-toolbar { flex-direction: column; align-items: flex-start; }
}

sp_widget.script:
(function() {
  data.programs     = [];
  data.categoryList = [];
  data.activePrograms = 0;
  data.totalPrograms  = 0;
  data.categories     = 0;

  var gr = new GlideRecordSecure('x_enno_gatenow_grant_program');
  gr.addQuery('active', true);
	gr.addQuery('status', 'accepting_proposals');
  gr.orderByDesc('sys_created_on');
  gr.query();

  var catSet = {};

  while (gr.next()) {
    var cat = gr.getDisplayValue('category') || ''; // ← confirm this exact field name in your table

    data.programs.push({
      sys_id:              gr.getUniqueValue(),
      program_name:        gr.getDisplayValue('program_name'),
      program_description: gr.getDisplayValue('program_description'),
      program_category:    cat,                              // ← must match what filter compares
      program_budget:      gr.getDisplayValue('program_budget'),
      proposal_open_date:  gr.getDisplayValue('proposal_open_date'),
      status:              gr.getDisplayValue('status')
    });

    if (cat) catSet[cat] = true;
  }

  data.totalPrograms  = data.programs.length;
  data.activePrograms = data.programs.length;
  data.categoryList   = Object.keys(catSet).sort();         // ← drives the filter tab buttons
  data.categories     = data.categoryList.length;
})();
